function validate([root]) {
  if (!Array.isArray(root)) return 'root is a list of values with null closing each group of children.';
  if (root.length === 0) return null;
  if (!Number.isSafeInteger(root[0])) return 'The list starts with the root value, an integer.';
  if (root.length > 1 && root[1] !== null) return 'The root value must be followed by a null.';
  const depth = [1];
  let owner = 0;
  let deepest = 1;
  for (let i = 2; i < root.length; i++) {
    if (owner >= depth.length) return 'Each group of children needs a node before it to own it.';
    if (root[i] === null) {
      owner++;
      continue;
    }
    if (!Number.isSafeInteger(root[i])) return 'Node values are integers.';
    depth.push(depth[owner] + 1);
    deepest = Math.max(deepest, depth[owner] + 1);
  }
  if (depth.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (deepest > 1000) return 'The tree is at most 1000 levels deep.';
  return null;
}

