function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val = 0, children = []) { this.val = val; this.children = children; }
  }
  // Rebuild the tree: nodes appear in breadth-first order, so nodes[owner] owns the group being read.
  const root = values.length > 0 ? new Node(values[0]) : null;
  const nodes = root ? [root] : [];
  let owner = 0;
  for (let i = 2; i < values.length; i++) {
    if (values[i] === null) {
      owner++;
      continue;
    }
    const child = new Node(values[i]);
    nodes[owner].children.push(child);
    nodes.push(child);
  }
  const before = nodes.map(node => [node.val, node.children, node.children.slice()]);
  const originals = new Set(nodes);
  const arrays = new Set(nodes.map(node => node.children));
  // The solution builds its copy with this N-ary Node class; the shared classes are restored afterwards.
  const saved = [globalThis.Node, globalThis._Node];
  globalThis.Node = Node;
  globalThis._Node = Node;
  let result;
  try {
    result = solve(root);
  } finally {
    globalThis.Node = saved[0];
    globalThis._Node = saved[1];
  }
  if (result === undefined) throw new Error('The solution did not return a value.');
  const intact = nodes.every((node, i) => node.val === before[i][0] && node.children === before[i][1] && node.children.length === before[i][2].length && node.children.every((child, j) => child === before[i][2][j]));
  if (!intact) throw new Error('The original tree must not be modified.');
  if (result === null) return [];
  if (typeof result !== 'object') throw new Error('Return the root node of the copy, or null for an empty tree.');
  // Serialize the copy breadth first, refusing original nodes, shared arrays and anything that is not a tree.
  const out = [result.val, null];
  const order = [result];
  const seen = new Set(order);
  for (let k = 0; k < order.length; k++) {
    const node = order[k];
    if (originals.has(node)) throw new Error('The copy must be made of new nodes; it reuses a node of the original tree.');
    if (!Array.isArray(node.children)) throw new Error('Every node of the copy needs a children array.');
    if (arrays.has(node.children)) throw new Error('The copy must not share a children array with the original tree.');
    for (const child of node.children) {
      if (!child || typeof child !== 'object') throw new Error('children may only hold nodes.');
      if (seen.has(child)) throw new Error('The copy must be a tree: no node may be reached twice.');
      seen.add(child);
      order.push(child);
      out.push(child.val);
    }
    out.push(null);
  }
  while (out.length > 0 && out[out.length - 1] === null) out.pop();
  return out;
}

