function cloneTree(root) {
  if (root === null) {
    return null;
  }
  const copy = new Node(root.val);
  for (const child of root.children) {
    copy.children.push(cloneTree(child));
  }
  return copy;
}

brute:
function cloneTree(root) {
  // Copy level by level with a queue of [original, copy] pairs, building plain objects.
  if (!root) return null;
  const top = { val: root.val, children: [] };
  const queue = [[root, top]];
  for (let q = 0; q < queue.length; q++) {
    const [from, to] = queue[q];
    for (const kid of from.children) {
      const made = { val: kid.val, children: [] };
      to.children.push(made);
      queue.push([kid, made]);
    }
  }
  return top;
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(90) : pick(9);
  if (n === 0) return [[]];
  const range = size === 'large' ? 10001 : rand() < 0.4 ? 4 : 30;
  const offset = rand() < 0.3 ? -Math.floor(range / 2) : 0;
  const shape = rand();
  const nodes = [{ val: pick(range) + offset, children: [] }];
  while (nodes.length < n) {
    // Deep trees grow from recent nodes, wide trees from a few early ones, mixed trees from anywhere.
    let parent;
    if (shape < 0.3) parent = nodes[Math.max(0, nodes.length - 1 - pick(3))];
    else if (shape < 0.5) parent = nodes[pick(Math.min(nodes.length, 3))];
    else parent = nodes[pick(nodes.length)];
    const child = { val: pick(range) + offset, children: [] };
    parent.children.push(child);
    nodes.push(child);
  }
  const values = [nodes[0].val, null];
  const order = [nodes[0]];
  for (let k = 0; k < order.length; k++) {
    for (const child of order[k].children) {
      order.push(child);
      values.push(child.val);
    }
    values.push(null);
  }
  while (values[values.length - 1] === null) values.pop();
  return [values];
}
